-- 落地断言：三列都不该有漏网的
SELECT COUNT(*) AS 未回填 FROM `question` WHERE `paper_id` IS NOT NULL AND (`topic` IS NULL OR `difficulty` IS NULL);
SELECT p.code, q.topic, COUNT(*) AS 题数, SUM(q.difficulty=3) AS 三星
  FROM `question` q JOIN `exam_paper` p ON p.id=q.paper_id
 GROUP BY p.code, q.topic ORDER BY p.sort_no, q.topic;
